    step.
    (* [comment removed for export] *)
    zstep. rewrite (Z.shiftr_div_pow2 (d_ids d + 1) 16), (Z.div_small (d_ids d + 1) (2^16)) by lia.
    zstep. zstep. step. step. if_cases K5; zify_cond K5. { exfalso. lia. }
    (* [comment removed for export] *)
