      assert (FR : rw_cells asegs mm (bv_unsigned sp + -112)
                ([CB 8 (firstn 8 (firstn 24 (firstn 32 (firstn 40 (firstn 48 (firstn 56 (firstn 64 (firstn 72 (firstn 80 (firstn 88 (firstn 96 (firstn 104 junk0))))))))))))]
